  const documentHeads=data?.documents.filter(doc=>data.documentHeadIds?.includes(doc.id))??[];
  const conversationRuns=data?.aiRuns?.filter(run=>run.conversationId===conversationId)??[];const runPending=conversationRuns.some(run=>['queued','running'].includes(run.status));
  const field=(key:string)=>({value:form[key]??'',onChange:(e:React.ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>{setForm(old=>({...old,[key]:e.target.value}));setConfirmed(false)}});
