  const after=async(command:WorkspaceCommand)=>{const result=await submit(command);if(result)close();return result};

  if(!data)return <div className={s.app} style={{display:'block'}}><header className={s.publicHeader}><Brand/><a href="/welcome" className={s.textButton}>About Kiara</a></header><div className={s.loading}>{!error&&<div className={s.spinner}/>}<h1 style={{fontSize:20,fontWeight:500}}>{authRequired?'Sign in to continue':'Opening your workspace'}</h1><p>{error||'Your conversations, context and work, together.'}</p>{authRequired&&<a className={s.primary} href="/api/v2/auth/start">Sign in with your organization</a>}{error&&<button className={s.button} onClick={()=>void refresh().catch(e=>setError(e.message))}>Reconnect</button>}</div></div>;

